## A texture's pixels as an image the pixel functions can read. The phone's textures are
## GPU-compressed (ASTC 4x4, tools/astc-pack.gd), which get_pixel, get_region, blit_rect and
## BitMap cannot use; this decompresses first. Everything else comes back exactly as get_image()
## returns it. Every texture.get_image() in the game goes through here on the phone (the overlay
## builder rewrites them).
static func plain_image(t) -> Image:
	if t == null:
		return null
	if t is AtlasTexture and t.atlas != null:
		var whole: Image = t.atlas.get_image()
		if whole != null and whole.is_compressed():
			whole.decompress()
			var r: = Rect2i(t.region).intersection(Rect2i(Vector2i.ZERO, whole.get_size()))
			return whole.get_region(r)
	var img: Image = t.get_image()
	if img != null and img.is_compressed():
		img.decompress()
	return img


